package com.agacostays.payment.client;
import com.agacostays.payment.dto.response.BookingResponse; import com.agacostays.payment.exception.BusinessRuleException; import tools.jackson.databind.JsonNode; import org.springframework.beans.factory.annotation.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.math.BigDecimal;
@Component public class BookingServiceClient { private final RestClient client; public BookingServiceClient(RestClient.Builder b,@Value("${services.booking.base-url}")String url){client=b.baseUrl(url).build();} public BookingResponse getBooking(Long id){try{JsonNode n=client.get().uri("/api/bookings/{id}",id).retrieve().body(JsonNode.class); return new BookingResponse(id,longV(n,"branchId"),longV(n,"customerId"),amount(n),text(n,"bookingStatus"),text(n,"paymentStatus"));}catch(Exception e){throw new BusinessRuleException("Booking service unavailable or booking not found");}} private Long longV(JsonNode n,String k){return n.path(k).isNumber()?n.get(k).longValue():null;} private BigDecimal amount(JsonNode n){for(String k:new String[]{"amount","totalAmount","price","bookingAmount","finalAmount"})if(n.path(k).isNumber())return n.get(k).decimalValue();return BigDecimal.ZERO;} private String text(JsonNode n,String k){return n.path(k).isMissingNode()?null:n.path(k).asText();} }
